contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry exercising C.transfer and asserting the general rule
    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        // precondition required by C.transfer
        require(_tos.length > 0, "_tos must be non-empty");
        // require array lengths match to avoid out-of-bounds in C
        require(v.length == _tos.length, "v and _tos must have same length");

        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // General rule: if the call did not revert then it must have returned true.
        // (This encodes that successful completion of transfer yields true.)
        assert(reverted || ret == true);
    }

    receive() external payable { }
}

